#include "baseline_isolated.hpp"
#include "control_isolated.hpp"
#include "early_isolated.hpp"
#include "guard_floyd_isolated.hpp"
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <ctime>
#include <string>
#include <limits>
static double cpu_now(){timespec t{};clock_gettime(CLOCK_THREAD_CPUTIME_ID,&t);return t.tv_sec*1e9+t.tv_nsec;}
static std::uint64_t state=123;
static std::uint64_t random_value(){state^=state<<13;state^=state>>7;state^=state<<17;return state;}
struct Result{double cpu,wall;std::uint64_t checksum;};
template<class H> [[gnu::noinline]] Result measure(const std::vector<int>& input,bool copy,int batch){
 std::vector<std::vector<int>> work; if(!copy)work.assign(batch,input);
 std::vector<H> output;output.reserve(batch);
 auto cpu=cpu_now();auto begin=std::chrono::steady_clock::now();std::atomic_signal_fence(std::memory_order_seq_cst);
 if(copy)for(int i=0;i<batch;++i)output.emplace_back(input);
 else for(int i=0;i<batch;++i)output.emplace_back(std::move(work[i]));
 std::atomic_signal_fence(std::memory_order_seq_cst);double wall=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-begin).count()/batch;cpu=(cpu_now()-cpu)/batch;
 std::uint64_t sum=0;for(auto&h:output){if(h.size()!=input.size() || (!input.empty()&&h.top()!=*std::min_element(input.begin(),input.end())))std::abort();sum=sum*113+static_cast<std::uint64_t>(h.top())+h.size();}
 return {cpu,wall,sum};
}
int main(int argc,char**argv){if(argc<4)return 2;auto n=static_cast<std::size_t>(std::strtoull(argv[1],nullptr,10));std::string shape=argv[2];bool copy=std::string(argv[3])=="copy";
 std::vector<int> input(n);for(std::size_t i=0;i<n;++i)input[i]=shape=="random"?static_cast<int>(random_value()):shape=="ascending"?static_cast<int>(i):shape=="descending"?static_cast<int>(n-i):shape=="equal"?7:static_cast<int>(i%2?i:n-i);
 using Fn=Result(*)(const std::vector<int>&,bool,int);Fn fs[]={measure<Heap_baseline>,measure<Heap_control>,measure<Heap_early>,measure<Heap_guard_floyd>};const char*names[]={"baseline","control","early","guard_floyd"};
 int batch=n<32?2048:n<2048?128:n<100000?8:2;
 for(int r=-3;r<15;++r)for(int k=0;k<4;++k){int v=(k+r+4)%4;auto result=fs[v](input,copy,batch);if(r>=0)std::printf("{\"n\":%zu,\"shape\":\"%s\",\"mode\":\"%s\",\"variant\":\"%s\",\"round\":%d,\"batch\":%d,\"cpu_ns\":%.3f,\"wall_ns\":%.3f,\"checksum\":%ju}\n",n,shape.c_str(),copy?"copy":"move",names[v],r,batch,result.cpu,result.wall,static_cast<std::uintmax_t>(result.checksum));}
}

