import pathlib,difflib,re
p=pathlib.Path('/tmp/sirkit_four_hours_20261022/graph/heap_round2');root=pathlib.Path('/home/reinsirk/Atcoder_Env');s=(root/'DataStructure/heap.cpp').read_text();(p/'baseline.hpp').write_text(s);(p/'control.hpp').write_text(s)
old='''    void make_heap() {
        std::make_heap(values_.begin(), values_.end(), std::greater<int>{});
    }'''
early='''    void make_heap() {
        const std::size_t count = values_.size();
        int* const data = values_.data();
        for (std::size_t root = count / 2; root != 0;) {
            --root;
            const int value = data[root];
            std::size_t position = root;
            while (position < count / 2) {
                std::size_t child = position * 2 + 1;
                if (child + 1 < count && data[child + 1] < data[child]) ++child;
                if (value <= data[child]) break;
                data[position] = data[child];
                position = child;
            }
            data[position] = value;
        }
    }'''
guard='''    void make_heap() {
        const std::size_t count = values_.size();
        int* const data = values_.data();
        for (std::size_t root = count / 2; root != 0;) {
            --root;
            std::size_t child = root * 2 + 1;
            if (child + 1 < count && data[child + 1] < data[child]) ++child;
            const int value = data[root];
            if (value <= data[child]) continue;
            data[root] = data[child];
            std::size_t position = child;
            while (position < count / 2) {
                child = position * 2 + 1;
                if (child + 1 < count && data[child + 1] < data[child]) ++child;
                data[position] = data[child];
                position = child;
            }
            while (position != root) {
                const std::size_t parent = (position - 1) / 2;
                if (data[parent] <= value) break;
                data[position] = data[parent];
                position = parent;
            }
            data[position] = value;
        }
    }'''
for name,body in [('early',early),('guard_floyd',guard)]:
 assert old in s;t=s.replace(old,body);(p/(name+'.hpp')).write_text(t);(p/(name+'.patch')).write_text(''.join(difflib.unified_diff(s.splitlines(True),t.splitlines(True),fromfile='baseline',tofile=name)))
for name in ['baseline','control','early','guard_floyd']:
 t=(p/(name+'.hpp')).read_text();t=re.sub(r'\bHeap\b','Heap_'+name,t).replace('SIRKIT_HEAP_DEFINED','SIRKIT_HEAP_'+name.upper()+'_DEFINED');(p/(name+'_isolated.hpp')).write_text(t)
for path in ['Verify/current/drivers/heap_prefix_kth_main.cpp','Verify/current/common/fast_io.hpp']:(p/pathlib.Path(path).name).write_bytes((root/path).read_bytes())

