  cmd=['taskset','-c','8','g++'if cc=='gcc'else'clang++',*(['--gcc-toolchain=/opt/atcoder/gcc']if cc=='clang'else[]),'-std=c++23','-O2',str(f),'-o',str(exe)];r=subprocess.run(cmd,capture_output=True,text=True);build.append(dict(command=cmd,returncode=r.returncode,stderr=r.stderr))
  if r.returncode:raise RuntimeError(r.stderr)
  sections[cc][v]={}
  for sec in ['.text','.rodata','.data']:
   out=p/(cc+'_'+v+sec);subprocess.run(['objcopy','--dump-section',sec+'='+str(out),str(exe)],check=True,capture_output=True);sections[cc][v][sec]=hashlib.sha256(out.read_bytes()).hexdigest()
cases=json.load(open('/tmp/sirkit_heap_20261022/cases.json'))
for cc in ['gcc','clang']:
 for case in cases:
