  for v in ['baseline','control','candidate']:
   r=subprocess.run(['taskset','-c','8',str(p/(cc+'_'+v+'_main'))],input=data,capture_output=True)
   if r.returncode or r.stdout!=expected:raise RuntimeError((cc,v,case['name'],r.stderr))
   validation.append(dict(compiler=cc,variant=v,case=case['name'],input_sha256=hashlib.sha256(data).hexdigest(),expected_sha256=hashlib.sha256(expected).hexdigest(),output_sha256=hashlib.sha256(r.stdout).hexdigest(),returncode=r.returncode))
with open('/tmp/sirkit_four_hours_20261022/benchmark_graph.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ['gcc','clang']:
  for name in ['asc_500000_k250000','desc_500000_k250000','random_500000_k250000','asc_16_k8','asc_500000_k1','asc_500000_k500000']:
   case=next(x for x in cases if x['name']==name);data=pathlib.Path(case['input']).read_bytes()
   for r in range(-1,9):
    vs=['baseline','control','candidate'];offset=(r+1)%3;vs=vs[offset:]+vs[:offset]
    for v in vs:
     while pathlib.Path('/tmp/sirkit_four_hours_20261022/pause_benchmarks').exists():time.sleep(.2)
     old=resource.getrusage(resource.RUSAGE_CHILDREN);begin=time.perf_counter_ns();proc=subprocess.run(['taskset','-c','20',str(p/(cc+'_'+v+'_main'))],input=data,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE);wall=time.perf_counter_ns()-begin;new=resource.getrusage(resource.RUSAGE_CHILDREN);cpu=(new.ru_utime+new.ru_stime-old.ru_utime-old.ru_stime)*1e9
     if proc.returncode:raise RuntimeError(proc.stderr)
